// Lifecycle status of a single task.
enum TaskStatus {
    TODO,        // not started yet
    IN_PROGRESS, // currently being worked on
    DONE         // finished
}

// How urgently a task should be worked on.
enum TaskPriority {
    LOW, MEDIUM, HIGH
}

// A single unit of work with its own dependency set.
class Task {
    private final String taskId;              // unique id, e.g. TASK-1
    private final String title;               // display title
    private final TaskPriority priority;       // urgency tier
    private TaskStatus status;                 // current lifecycle state
    private final java.util.Set<String> dependencies = new java.util.HashSet<>(); // task ids that must be DONE first

    public Task(String taskId, String title, TaskPriority priority) {
        this.taskId = taskId;      // store id
        this.title = title;         // store title
        this.priority = priority;   // store priority
        this.status = TaskStatus.TODO; // new tasks start as TODO
    }

    public String getTaskId() { return taskId; }               // id getter
    public String getTitle() { return title; }                  // title getter
    public TaskPriority getPriority() { return priority; }       // priority getter
    public TaskStatus getStatus() { return status; }              // status getter
    public void setStatus(TaskStatus status) { this.status = status; } // status setter
    public java.util.Set<String> getDependencies() { return dependencies; } // dependencies getter
    public void addDependency(String dependsOnId) { dependencies.add(dependsOnId); } // record a new dependency
}

// Creates tasks with sequential ids.
class TaskFactory {
    private int counter = 0; // running id counter across all tasks created

    public Task createTask(String title, TaskPriority priority) {
        counter++;                                   // bump id counter
        return new Task("TASK-" + counter, title, priority); // e.g. TASK-1
    }
}

