// Strategy interface: how the next task to work on is chosen.
interface TaskPrioritizationStrategy {
    // Returns the chosen task, or null if the candidate list is empty.
    Task pickNext(java.util.List<Task> unblockedTodoTasks);
}

// Picks the highest-priority candidate, breaking ties by lowest task id (earliest created).
class HighestPriorityFirstStrategy implements TaskPrioritizationStrategy {
    @Override
    public Task pickNext(java.util.List<Task> unblockedTodoTasks) {
        Task best = null;                                        // best candidate found so far
        for (Task t : unblockedTodoTasks) {                        // scan all eligible tasks
            if (best == null
                    || t.getPriority().ordinal() > best.getPriority().ordinal() // strictly higher priority wins
                    || (t.getPriority() == best.getPriority() && t.getTaskId().compareTo(best.getTaskId()) < 0)) { // tie: earlier id wins
                best = t; // remember it
            }
        }
        return best; // the chosen task, or null if the list was empty
    }
}

