#include <vector>
using namespace std;

// Strategy interface: how the next task to work on is chosen.
class TaskPrioritizationStrategy {
public:
    // Returns a pointer to the chosen task, or nullptr if the candidate list is empty.
    virtual Task* pickNext(vector<Task*>& unblockedTodoTasks) = 0;
    virtual ~TaskPrioritizationStrategy() {}
};

// Picks the highest-priority candidate, breaking ties by lowest task id (earliest created).
class HighestPriorityFirstStrategy : public TaskPrioritizationStrategy {
public:
    Task* pickNext(vector<Task*>& unblockedTodoTasks) override {
        Task* best = nullptr;                                       // best candidate found so far
        for (Task* t : unblockedTodoTasks) {                          // scan all eligible tasks
            if (best == nullptr
                    || (int)t->priority > (int)best->priority             // strictly higher priority wins
                    || (t->priority == best->priority && t->taskId < best->taskId)) { // tie: earlier id wins
                best = t; // remember it
            }
        }
        return best; // the chosen task, or nullptr if the list was empty
    }
};

