interface TaskObserver {
    void onTaskCreated(Task task);                                   // new task created
    void onDependencyRejected(String taskId, String dependsOnId);      // would-be cycle rejected
    void onTaskStarted(Task task);                                     // task moved to IN_PROGRESS
    void onTaskBlocked(String taskId, String reason);                  // start attempt rejected
    void onTaskCompleted(Task task);                                    // task moved to DONE
}

// Simple observer that prints events to the console.
class ConsoleTaskObserver implements TaskObserver {
    @Override
    public void onTaskCreated(Task task) {
        System.out.println("Task " + task.getTaskId() + " created: " + task.getTitle() + " (" + task.getPriority() + ")");
    }

    @Override
    public void onDependencyRejected(String taskId, String dependsOnId) {
        System.out.println("Dependency rejected: " + taskId + " depends on " + dependsOnId + " would create a cycle");
    }

    @Override
    public void onTaskStarted(Task task) {
        System.out.println("Task " + task.getTaskId() + " started");
    }

    @Override
    public void onTaskBlocked(String taskId, String reason) {
