    }
}

// Custom exceptions for the realistic failure modes.
class DependencyCycleException extends RuntimeException {
    public DependencyCycleException(String msg) { super(msg); }
}
class TaskBlockedException extends RuntimeException {
    public TaskBlockedException(String msg) { super(msg); }
}
class InvalidTaskException extends RuntimeException {
    public InvalidTaskException(String msg) { super(msg); }
}

// The core orchestrator tying every piece together.
class TaskManagementService {
    private final java.util.Map<String, Task> tasks = new java.util.HashMap<>(); // taskId -> Task
    private final TaskPrioritizationStrategy prioritizationStrategy; // pluggable selection policy
    private final java.util.List<TaskObserver> observers = new java.util.ArrayList<>(); // listeners

    public TaskManagementService(TaskPrioritizationStrategy prioritizationStrategy) {
        this.prioritizationStrategy = prioritizationStrategy; // store chosen policy
    }

    public void addObserver(TaskObserver observer) { observers.add(observer); } // register a listener

    public Task createTask(String title, TaskPriority priority, TaskFactory factory) {
        Task task = factory.createTask(title, priority); // build the task
        tasks.put(task.getTaskId(), task);                 // store it
        for (TaskObserver obs : observers) obs.onTaskCreated(task); // notify
        return task; // hand back to caller
    }

    // True if 'to' is reachable from 'from' by following dependency edges.
    private boolean reachable(String from, String to) {
        java.util.Set<String> visited = new java.util.HashSet<>();  // nodes already explored
        java.util.Deque<String> stack = new java.util.ArrayDeque<>(); // DFS stack
        stack.push(from);                                              // start from 'from'
        while (!stack.isEmpty()) {                                      // explore until exhausted
            String current = stack.pop();                                 // next node to check
            if (current.equals(to)) return true;                           // found the target
            if (!visited.add(current)) continue;                           // skip already-visited nodes
            Task currentTask = tasks.get(current);                          // look up its dependencies
            if (currentTask != null) {
                for (String dep : currentTask.getDependencies()) stack.push(dep); // explore each dependency
            }
        }
        return false; // 'to' is not reachable from 'from'
    }

    // Adds a dependency edge if it would not create a cycle.
    public synchronized void addDependency(String taskId, String dependsOnId) {
        if (reachable(dependsOnId, taskId)) {                          // dependsOnId already leads back to taskId
            for (TaskObserver obs : observers) obs.onDependencyRejected(taskId, dependsOnId); // notify
            throw new DependencyCycleException("Adding " + taskId + " depends on " + dependsOnId + " would create a cycle");
        }
        tasks.get(taskId).addDependency(dependsOnId); // safe to add: no cycle
    }

    // Starts a task if every dependency is already DONE.
    public synchronized void startTask(String taskId) {
        Task task = tasks.get(taskId);                                  // look up task
        if (task == null) throw new InvalidTaskException("Unknown task: " + taskId);
        for (String depId : task.getDependencies()) {                     // check every dependency
            if (tasks.get(depId).getStatus() != TaskStatus.DONE) {           // one is not finished
                for (TaskObserver obs : observers) obs.onTaskBlocked(taskId, "Blocked by incomplete dependencies"); // notify
                throw new TaskBlockedException("Task " + taskId + " is blocked by incomplete dependencies");
            }
        }
        task.setStatus(TaskStatus.IN_PROGRESS);                            // all dependencies satisfied
        for (TaskObserver obs : observers) obs.onTaskStarted(task);       // notify
    }

    // Completes a task that is currently IN_PROGRESS.
    public synchronized void completeTask(String taskId) {
        Task task = tasks.get(taskId);                                  // look up task
        if (task == null || task.getStatus() != TaskStatus.IN_PROGRESS) {
            throw new InvalidTaskException("Task " + taskId + " is not in progress");
        }
        task.setStatus(TaskStatus.DONE);                                  // mark done
        for (TaskObserver obs : observers) obs.onTaskCompleted(task);    // notify
    }

    // Returns the highest-priority task among those with all dependencies DONE.
    public Task getNextAvailableTask() {
        java.util.List<Task> candidates = new java.util.ArrayList<>();  // eligible tasks
        for (Task task : tasks.values()) {                                // scan all tasks
            if (task.getStatus() != TaskStatus.TODO) continue;              // must still be TODO
            boolean unblocked = true;                                       // assume unblocked until proven otherwise
            for (String depId : task.getDependencies()) {                    // check every dependency
                if (tasks.get(depId).getStatus() != TaskStatus.DONE) { unblocked = false; break; } // one incomplete blocks it
            }
            if (unblocked) candidates.add(task);                              // this task is eligible
        }
        return prioritizationStrategy.pickNext(candidates); // delegate the final choice to the strategy
    }
}

