# Custom exceptions for the realistic failure modes.
class DependencyCycleException(Exception): pass
class TaskBlockedException(Exception): pass
class InvalidTaskException(Exception): pass

# The core orchestrator tying every piece together.
class TaskManagementService:
    def __init__(self, prioritization_strategy):
        self.tasks = {}  # taskId -> Task
        self.prioritization_strategy = prioritization_strategy  # pluggable selection policy
        self.observers = []  # listeners

    def add_observer(self, observer):
        self.observers.append(observer)  # register a listener

    def create_task(self, title, priority, factory):
        task = factory.create_task(title, priority)  # build the task
        self.tasks[task.task_id] = task                # store it
        for obs in self.observers:
            obs.on_task_created(task)  # notify
        return task  # hand back to caller

    def _reachable(self, from_id, to_id):
        visited = set()          # nodes already explored
        stack = [from_id]          # DFS stack, start from 'from_id'
        while stack:                # explore until exhausted
            current = stack.pop()      # next node to check
            if current == to_id:
                return True              # found the target
            if current in visited:
                continue                  # skip already-visited nodes
            visited.add(current)
            current_task = self.tasks.get(current)  # look up its dependencies
            if current_task is not None:
                for dep in current_task.dependencies:
                    stack.append(dep)  # explore each dependency
        return False  # 'to_id' is not reachable from 'from_id'

    def add_dependency(self, task_id, depends_on_id):
        if self._reachable(depends_on_id, task_id):  # depends_on_id already leads back to task_id
            for obs in self.observers:
                obs.on_dependency_rejected(task_id, depends_on_id)  # notify
            raise DependencyCycleException(f"Adding {task_id} depends on {depends_on_id} would create a cycle")
        self.tasks[task_id].add_dependency(depends_on_id)  # safe to add: no cycle

    def start_task(self, task_id):
        task = self.tasks.get(task_id)  # look up task
        if task is None:
            raise InvalidTaskException(f"Unknown task: {task_id}")
        for dep_id in task.dependencies:  # check every dependency
            if self.tasks[dep_id].status != TaskStatus.DONE:  # one is not finished
                for obs in self.observers:
                    obs.on_task_blocked(task_id, "Blocked by incomplete dependencies")  # notify
                raise TaskBlockedException(f"Task {task_id} is blocked by incomplete dependencies")
        task.status = TaskStatus.IN_PROGRESS  # all dependencies satisfied
        for obs in self.observers:
            obs.on_task_started(task)  # notify

    def complete_task(self, task_id):
        task = self.tasks.get(task_id)  # look up task
        if task is None or task.status != TaskStatus.IN_PROGRESS:
            raise InvalidTaskException(f"Task {task_id} is not in progress")
        task.status = TaskStatus.DONE  # mark done
        for obs in self.observers:
            obs.on_task_completed(task)  # notify

