        candidates = []  # eligible tasks
        for task in self.tasks.values():  # scan all tasks
            if task.status != TaskStatus.TODO:
                continue  # must still be TODO
            unblocked = True  # assume unblocked until proven otherwise
            for dep_id in task.dependencies:  # check every dependency
                if self.tasks[dep_id].status != TaskStatus.DONE:
                    unblocked = False
                    break  # one incomplete blocks it
