using namespace std;

// Observer interface: reacts to task lifecycle events.
class TaskObserver {
public:
    virtual void onTaskCreated(const Task& task) = 0;
    virtual void onDependencyRejected(const string& taskId, const string& dependsOnId) = 0;
    virtual void onTaskStarted(const Task& task) = 0;
    virtual void onTaskBlocked(const string& taskId, const string& reason) = 0;
    virtual void onTaskCompleted(const Task& task) = 0;
    virtual ~TaskObserver() {}
};

// Simple observer that prints events to the console.
class ConsoleTaskObserver : public TaskObserver {
public:
    void onTaskCreated(const Task& task) override {
        cout << "Task " << task.taskId << " created: " << task.title << endl;
    }
    void onDependencyRejected(const string& taskId, const string& dependsOnId) override {
        cout << "Dependency rejected: " << taskId << " depends on " << dependsOnId << " would create a cycle" << endl;
    }
    void onTaskStarted(const Task& task) override {
        cout << "Task " << task.taskId << " started" << endl;
    }
    void onTaskBlocked(const string& taskId, const string& reason) override {
        cout << "Task " << taskId << " blocked: " << reason << endl;
    }
    void onTaskCompleted(const Task& task) override {
        cout << "Task " << task.taskId << " completed" << endl;
    }
};

// Custom exceptions for the realistic failure modes.
class DependencyCycleException : public runtime_error {
public: DependencyCycleException(const string& msg) : runtime_error(msg) {}
};
class TaskBlockedException : public runtime_error {
public: TaskBlockedException(const string& msg) : runtime_error(msg) {}
};
class InvalidTaskException : public runtime_error {
public: InvalidTaskException(const string& msg) : runtime_error(msg) {}
};

// The core orchestrator tying every piece together.
class TaskManagementService {
    map<string, Task> tasks;                                    // taskId -> Task
    shared_ptr<TaskPrioritizationStrategy> prioritizationStrategy; // pluggable selection policy
    vector<shared_ptr<TaskObserver>> observers;                   // listeners

    // True if 'to' is reachable from 'from' by following dependency edges.
    bool reachable(string from, string to) {
        set<string> visited;               // nodes already explored
        vector<string> stack;                // DFS stack
        stack.push_back(from);                 // start from 'from'
        while (!stack.empty()) {                 // explore until exhausted
            string current = stack.back();          // next node to check
            stack.pop_back();
            if (current == to) return true;           // found the target
            if (visited.count(current)) continue;      // skip already-visited nodes
            visited.insert(current);
            auto it = tasks.find(current);               // look up its dependencies
            if (it != tasks.end()) {
                for (auto& dep : it->second.dependencies) stack.push_back(dep); // explore each dependency
            }
        }
        return false; // 'to' is not reachable from 'from'
    }

public:
    TaskManagementService(shared_ptr<TaskPrioritizationStrategy> strategy) : prioritizationStrategy(strategy) {}

    void addObserver(shared_ptr<TaskObserver> observer) { observers.push_back(observer); } // register a listener

    Task createTask(string title, TaskPriority priority, TaskFactory& factory) {
        Task task = factory.createTask(title, priority); // build the task
        tasks.insert({task.taskId, task});                 // store it
        for (auto& obs : observers) obs->onTaskCreated(tasks.at(task.taskId)); // notify
        return tasks.at(task.taskId); // hand back to caller
    }

    void addDependency(string taskId, string dependsOnId) {
        if (reachable(dependsOnId, taskId)) {              // dependsOnId already leads back to taskId
            for (auto& obs : observers) obs->onDependencyRejected(taskId, dependsOnId); // notify
            throw DependencyCycleException("Adding " + taskId + " depends on " + dependsOnId + " would create a cycle");
        }
        tasks.at(taskId).addDependency(dependsOnId); // safe to add: no cycle
    }

    void startTask(string taskId) {
        auto it = tasks.find(taskId);                        // look up task
        if (it == tasks.end()) throw InvalidTaskException("Unknown task: " + taskId);
        Task& task = it->second;
        for (auto& depId : task.dependencies) {                 // check every dependency
            if (tasks.at(depId).status != TaskStatus::DONE) {      // one is not finished
                for (auto& obs : observers) obs->onTaskBlocked(taskId, "Blocked by incomplete dependencies"); // notify
                throw TaskBlockedException("Task " + taskId + " is blocked by incomplete dependencies");
            }
        }
        task.status = TaskStatus::IN_PROGRESS;                   // all dependencies satisfied
        for (auto& obs : observers) obs->onTaskStarted(task);   // notify
    }

    void completeTask(string taskId) {
        auto it = tasks.find(taskId);                          // look up task
        if (it == tasks.end() || it->second.status != TaskStatus::IN_PROGRESS) {
            throw InvalidTaskException("Task " + taskId + " is not in progress");
        }
        it->second.status = TaskStatus::DONE;                    // mark done
        for (auto& obs : observers) obs->onTaskCompleted(it->second); // notify
    }

    Task* getNextAvailableTask() {
        vector<Task*> candidates;                               // eligible tasks
        for (auto& entry : tasks) {                                // scan all tasks
            Task& task = entry.second;
            if (task.status != TaskStatus::TODO) continue;           // must still be TODO
            bool unblocked = true;                                    // assume unblocked until proven otherwise
            for (auto& depId : task.dependencies) {                     // check every dependency
                if (tasks.at(depId).status != TaskStatus::DONE) { unblocked = false; break; } // one incomplete blocks it
            }
            if (unblocked) candidates.push_back(&task);               // this task is eligible
        }
        return prioritizationStrategy->pickNext(candidates); // delegate the final choice to the strategy
    }
};

