import java.util.*;

public class Main {
    public static void main(String[] args) {
        TaskManagementService service = new TaskManagementService(new HighestPriorityFirstStrategy());
        service.addObserver(new ConsoleTaskObserver());
        TaskFactory factory = new TaskFactory();

        Task t1 = service.createTask("Design API", TaskPriority.HIGH, factory);
        Task t2 = service.createTask("Implement API", TaskPriority.HIGH, factory);
        Task t3 = service.createTask("Write Tests", TaskPriority.MEDIUM, factory);
        Task t4 = service.createTask("Deploy", TaskPriority.LOW, factory);
        Task t5 = service.createTask("Write Docs", TaskPriority.LOW, factory);

        service.addDependency(t2.getTaskId(), t1.getTaskId());
        service.addDependency(t3.getTaskId(), t2.getTaskId());
        service.addDependency(t4.getTaskId(), t3.getTaskId());

        try {
            service.addDependency(t1.getTaskId(), t4.getTaskId());
        } catch (DependencyCycleException e) {
            System.out.println("Caught expected: " + e.getMessage());
        }

        Task next = service.getNextAvailableTask();
        System.out.println("Next available task: " + next.getTaskId());

        try {
            service.startTask(t2.getTaskId());
        } catch (TaskBlockedException e) {
            System.out.println("Caught expected: " + e.getMessage());
        }

        service.startTask(t1.getTaskId());
        service.completeTask(t1.getTaskId());
        service.startTask(t2.getTaskId());
    }
}

