        tasks.put(task.getTaskId(), task);
        for (TaskObserver obs : observers) obs.onTaskCreated(task);
        return task;
    }

    private boolean reachable(String from, String to) {
        Set<String> visited = new HashSet<>();
        Deque<String> stack = new ArrayDeque<>();
        stack.push(from);
        while (!stack.isEmpty()) {
            String current = stack.pop();
            if (current.equals(to)) return true;
            if (!visited.add(current)) continue;
            Task currentTask = tasks.get(current);
            if (currentTask != null) {
                for (String dep : currentTask.getDependencies()) stack.push(dep);
            }
        }
        return false;
    }

    public synchronized void addDependency(String taskId, String dependsOnId) {
        if (reachable(dependsOnId, taskId)) {
            for (TaskObserver obs : observers) obs.onDependencyRejected(taskId, dependsOnId);
            throw new DependencyCycleException("Adding " + taskId + " depends on " + dependsOnId + " would create a cycle");
        }
        tasks.get(taskId).addDependency(dependsOnId);
    }

    public synchronized void startTask(String taskId) {
        Task task = tasks.get(taskId);
        if (task == null) throw new InvalidTaskException("Unknown task: " + taskId);
        for (String depId : task.getDependencies()) {
            if (tasks.get(depId).getStatus() != TaskStatus.DONE) {
                for (TaskObserver obs : observers) obs.onTaskBlocked(taskId, "Blocked by incomplete dependencies");
                throw new TaskBlockedException("Task " + taskId + " is blocked by incomplete dependencies");
            }
        }
        task.setStatus(TaskStatus.IN_PROGRESS);
        for (TaskObserver obs : observers) obs.onTaskStarted(task);
    }

    public synchronized void completeTask(String taskId) {
        Task task = tasks.get(taskId);
        if (task == null || task.getStatus() != TaskStatus.IN_PROGRESS) {
            throw new InvalidTaskException("Task " + taskId + " is not in progress");
        }
        task.setStatus(TaskStatus.DONE);
        for (TaskObserver obs : observers) obs.onTaskCompleted(task);
    }

    public Task getNextAvailableTask() {
        List<Task> candidates = new ArrayList<>();
        for (Task task : tasks.values()) {
            if (task.getStatus() != TaskStatus.TODO) continue;
            boolean unblocked = true;
            for (String depId : task.getDependencies()) {
                if (tasks.get(depId).getStatus() != TaskStatus.DONE) { unblocked = false; break; }
            }
            if (unblocked) candidates.add(task);
        }
        return prioritizationStrategy.pickNext(candidates);
    }
}

