#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <set>
#include <memory>
#include <stdexcept>
using namespace std;

enum class TaskStatus { TODO, IN_PROGRESS, DONE };
enum class TaskPriority { LOW, MEDIUM, HIGH };

class Task {
public:
    string taskId;
    string title;
    TaskPriority priority;
    TaskStatus status;
    set<string> dependencies;

    Task() {}
    Task(string id, string t, TaskPriority p)
        : taskId(id), title(t), priority(p), status(TaskStatus::TODO) {}

    void addDependency(string dependsOnId) { dependencies.insert(dependsOnId); }
};

class TaskFactory {
    int counter = 0;

public:
    Task createTask(string title, TaskPriority priority) {
        counter++;
        return Task("TASK-" + to_string(counter), title, priority);
    }
};

class TaskPrioritizationStrategy {
public:
    virtual Task* pickNext(vector<Task*>& unblockedTodoTasks) = 0;
    virtual ~TaskPrioritizationStrategy() {}
};

class HighestPriorityFirstStrategy : public TaskPrioritizationStrategy {
public:
    Task* pickNext(vector<Task*>& unblockedTodoTasks) override {
        Task* best = nullptr;
        for (Task* t : unblockedTodoTasks) {
            if (best == nullptr
                    || (int)t->priority > (int)best->priority
                    || (t->priority == best->priority && t->taskId < best->taskId)) {
                best = t;
            }
        }
        return best;
    }
};

class TaskObserver {
public:
    virtual void onTaskCreated(const Task& task) = 0;
    virtual void onDependencyRejected(const string& taskId, const string& dependsOnId) = 0;
    virtual void onTaskStarted(const Task& task) = 0;
    virtual void onTaskBlocked(const string& taskId, const string& reason) = 0;
    virtual void onTaskCompleted(const Task& task) = 0;
    virtual ~TaskObserver() {}
};

class ConsoleTaskObserver : public TaskObserver {
public:
    void onTaskCreated(const Task& task) override {
        cout << "Task " << task.taskId << " created: " << task.title << endl;
    }
    void onDependencyRejected(const string& taskId, const string& dependsOnId) override {
        cout << "Dependency rejected: " << taskId << " depends on " << dependsOnId << " would create a cycle" << endl;
    }
    void onTaskStarted(const Task& task) override {
        cout << "Task " << task.taskId << " started" << endl;
    }
    void onTaskBlocked(const string& taskId, const string& reason) override {
        cout << "Task " << taskId << " blocked: " << reason << endl;
    }
    void onTaskCompleted(const Task& task) override {
        cout << "Task " << task.taskId << " completed" << endl;
    }
};

class DependencyCycleException : public runtime_error {
public: DependencyCycleException(const string& msg) : runtime_error(msg) {}
};
class TaskBlockedException : public runtime_error {
public: TaskBlockedException(const string& msg) : runtime_error(msg) {}
};
class InvalidTaskException : public runtime_error {
public: InvalidTaskException(const string& msg) : runtime_error(msg) {}
};

class TaskManagementService {
    map<string, Task> tasks;
    shared_ptr<TaskPrioritizationStrategy> prioritizationStrategy;
    vector<shared_ptr<TaskObserver>> observers;

    bool reachable(string from, string to) {
        set<string> visited;
        vector<string> stack;
        stack.push_back(from);
        while (!stack.empty()) {
            string current = stack.back();
            stack.pop_back();
            if (current == to) return true;
            if (visited.count(current)) continue;
            visited.insert(current);
            auto it = tasks.find(current);
            if (it != tasks.end()) {
                for (auto& dep : it->second.dependencies) stack.push_back(dep);
            }
        }
        return false;
    }

public:
    TaskManagementService(shared_ptr<TaskPrioritizationStrategy> strategy) : prioritizationStrategy(strategy) {}

    void addObserver(shared_ptr<TaskObserver> observer) { observers.push_back(observer); }

    Task createTask(string title, TaskPriority priority, TaskFactory& factory) {
        Task task = factory.createTask(title, priority);
        tasks.insert({task.taskId, task});
        for (auto& obs : observers) obs->onTaskCreated(tasks.at(task.taskId));
        return tasks.at(task.taskId);
    }

    void addDependency(string taskId, string dependsOnId) {
        if (reachable(dependsOnId, taskId)) {
            for (auto& obs : observers) obs->onDependencyRejected(taskId, dependsOnId);
            throw DependencyCycleException("Adding " + taskId + " depends on " + dependsOnId + " would create a cycle");
        }
        tasks.at(taskId).addDependency(dependsOnId);
    }

    void startTask(string taskId) {
        auto it = tasks.find(taskId);
        if (it == tasks.end()) throw InvalidTaskException("Unknown task: " + taskId);
        Task& task = it->second;
        for (auto& depId : task.dependencies) {
            if (tasks.at(depId).status != TaskStatus::DONE) {
                for (auto& obs : observers) obs->onTaskBlocked(taskId, "Blocked by incomplete dependencies");
                throw TaskBlockedException("Task " + taskId + " is blocked by incomplete dependencies");
            }
        }
        task.status = TaskStatus::IN_PROGRESS;
        for (auto& obs : observers) obs->onTaskStarted(task);
    }

    void completeTask(string taskId) {
        auto it = tasks.find(taskId);
        if (it == tasks.end() || it->second.status != TaskStatus::IN_PROGRESS) {
            throw InvalidTaskException("Task " + taskId + " is not in progress");
        }
        it->second.status = TaskStatus::DONE;
        for (auto& obs : observers) obs->onTaskCompleted(it->second);
    }

    Task* getNextAvailableTask() {
        vector<Task*> candidates;
        for (auto& entry : tasks) {
            Task& task = entry.second;
            if (task.status != TaskStatus::TODO) continue;
            bool unblocked = true;
            for (auto& depId : task.dependencies) {
                if (tasks.at(depId).status != TaskStatus::DONE) { unblocked = false; break; }
            }
            if (unblocked) candidates.push_back(&task);
        }
        return prioritizationStrategy->pickNext(candidates);
    }
};

int main() {
    auto service = TaskManagementService(make_shared<HighestPriorityFirstStrategy>());
    service.addObserver(make_shared<ConsoleTaskObserver>());
    TaskFactory factory;

    Task t1 = service.createTask("Design API", TaskPriority::HIGH, factory);
    Task t2 = service.createTask("Implement API", TaskPriority::HIGH, factory);
    Task t3 = service.createTask("Write Tests", TaskPriority::MEDIUM, factory);
    Task t4 = service.createTask("Deploy", TaskPriority::LOW, factory);
    Task t5 = service.createTask("Write Docs", TaskPriority::LOW, factory);

    service.addDependency(t2.taskId, t1.taskId);
    service.addDependency(t3.taskId, t2.taskId);
    service.addDependency(t4.taskId, t3.taskId);

    try {
        service.addDependency(t1.taskId, t4.taskId);
    } catch (DependencyCycleException& e) {
        cout << "Caught expected: " << e.what() << endl;
    }

    Task* next = service.getNextAvailableTask();
    cout << "Next available task: " << next->taskId << endl;

    try {
        service.startTask(t2.taskId);
    } catch (TaskBlockedException& e) {
        cout << "Caught expected: " << e.what() << endl;
    }

    service.startTask(t1.taskId);
    service.completeTask(t1.taskId);
    service.startTask(t2.taskId);

    return 0;
}
